def objs(g):
    g=np.array(g); seen=np.zeros_like(g,bool); out=[]
    for i in range(g.shape[0]):
        for j in range(g.shape[1]):
            if g[i,j] and not seen[i,j]:
                c=int(g[i,j]); st=[(i,j)]; seen[i,j]=1; cells=set()
                while st:
                    a,b=st.pop(); cells.add((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<g.shape[0] and 0<=y<g.shape[1] and not seen[x,y] and g[x,y]==c:
                            seen[x,y]=1; st.append((x,y))
                out.append((c,cells))
    return out
def norm(cells):
    rs=[r for r,_ in cells]; cs=[c for _,c in cells]
    return frozenset((r-min(rs),c-min(cs)) for r,c in cells)
def variants(cells):
    s=set(cells); res=set()
    cur=s
    for _ in range(4):
        res.add(norm(cur))
        cur={(c,-r) for r,c in cur}  # rotate
    cur={(r,-c) for r,c in s}  # mirror
    for _ in range(4):
        res.add(norm(cur))
        cur={(c,-r) for r,c in cur}
    return res
def transform(g):
